import json,pathlib,subprocess,time
ROOT=pathlib.Path('/var/lib/twin-release/paid-photo-20261030-7b6d9fb')
TESTS={"test_manual_attachment_history_pg.py":"\"\"\"A manually selected photo does not depend on archive recovery; controls still apply.\"\"\"\nfrom datetime import timedelta\nimport json\n\nimport pytest\nfrom sqlalchemy import select, func\nfrom sqlalchemy.orm import Session\n\nfrom test_onlyfans_foundation_pg import database\nfrom test_manual_vault_composer_pg import prepared, prepare, spec, FAN\nfrom test_onlyfans_connections_pg import TENANT\nfrom db.models import Fan, OfConversationState, ContentOffer, Message, VaultSend\nfrom db.onlyfans_models import OfIngress, OfRuntime\nfrom db.onlyfans_delivery_models import OfDeliveryPolicy, OfTextIntent\nfrom onlyfans_runtime.store import Refused, utcnow\nfrom onlyfans_runtime.text_delivery import SyntheticTextTransport\n\n\ndef history_hold(engine, account, *, stale=False):\n    with Session(engine) as s, s.begin():\n        runtime = s.get(OfRuntime, account)\n        s.add(OfIngress(account_id=account, binding_id=runtime.binding_id,\n            event_key=\"synthetic-unrelated-history\", fan_id=202, message_id=99,\n            source=\"import\", payload='{\"synthetic\":\"retain\"}', status=\"quarantined\",\n            reason=\"synthetic_conflict\", received_at=utcnow()))\n        if stale:\n            runtime.recovery_needed = True\n            runtime.pending_events = 1\n            runtime.last_sync_at = utcnow() - timedelta(hours=2)\n\n\n@pytest.mark.parametrize(\"price\", [0, 1200])\n@pytest.mark.parametrize(\"stage\", [\"prepare\", \"queued\", \"admitted\"])\n@pytest.mark.parametrize(\"stale\", [False, True])\ndef test_manual_attachment_survives_archive_hold_at_every_send_boundary(database, monkeypatch, stage, stale, price):\n    store, authority, account = prepared(database, monkeypatch)\n    try:\n        if stage == \"prepare\":\n            history_hold(database[1], account, stale=stale)\n        identity = prepare(authority, account, spec(price), body=\"\")\n        assert prepare(authority, account, spec(price), body=\"\") == identity\n        if stage == \"queued\":\n            history_hold(database[1], account, stale=stale)\n        if stage == \"admitted\":\n            grant = authority.admit(TENANT, account, identity)\n            assert not isinstance(grant, str)\n            history_hold(database[1], account, stale=stale)\n            assert authority.consume_dispatch(TENANT, grant) is not None\n        else:\n            wire = SyntheticTextTransport(account)\n            assert authority.dispatch(TENANT, account, identity, wire) == \"accepted\"\n            assert authority.dispatch(TENANT, account, identity, wire) == \"accepted\"\n            assert len(wire.calls) == 1\n            assert wire.calls[0].media_ids == (11, 13) and wire.calls[0].price_cents == price\n            with Session(database[1]) as s:\n                assert s.scalar(select(func.count()).select_from(ContentOffer)) == (1 if price else 0)\n                assert s.scalar(select(func.count()).select_from(Message)) == 1\n        with Session(database[1]) as s:\n            evidence = s.get(OfIngress, (account, \"synthetic-unrelated-history\"))\n            assert evidence.status == \"quarantined\" and json.loads(evidence.payload) == {\"synthetic\": \"retain\"}\n            assert s.get(OfConversationState, (account, FAN)).mode == \"human_controlled\"\n            assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 1\n    finally:\n        store.close()\n\n\n@pytest.mark.parametrize(\"kind\", [\"text\", \"automated\", \"campaign\", \"engagement\"])\ndef test_exception_does_not_bypass_history_for_other_send_origins(database, monkeypatch, kind):\n    store, authority, account = prepared(database, monkeypatch)\n    try:\n        history_hold(database[1], account)\n        with Session(database[1]) as s:\n            runtime = s.get(OfRuntime, account)\n            policy = s.get(OfDeliveryPolicy, account)\n            state = s.get(OfConversationState, (account, FAN))\n            fan = s.get(Fan, (account, FAN))\n            assert authority._eligibility(s, runtime, policy, state, fan,\n                \"manual\" if kind == \"text\" else kind, utcnow(),\n                manual_attachment=kind != \"text\") == \"history_quarantined\"\n    finally:\n        store.close()\n\n\n@pytest.mark.parametrize(\"price\", [0, 1200])\n@pytest.mark.parametrize(\"change\", [\"paused\", \"muted\", \"takeover_pending\", \"unknown\", \"disabled\", \"media_disabled\"])\ndef test_manual_photo_still_respects_operator_and_delivery_controls(database, monkeypatch, change, price):\n    store, authority, account = prepared(database, monkeypatch)\n    try:\n        history_hold(database[1], account, stale=True)\n        with Session(database[1]) as s, s.begin():\n            state = s.get(OfConversationState, (account, FAN))\n            policy = s.get(OfDeliveryPolicy, account)\n            if change == \"paused\": state.mode = \"paused\"\n            elif change == \"muted\": s.get(Fan, (account, FAN)).is_muted = True\n            elif change == \"takeover_pending\": state.takeover_state = \"requested\"\n            elif change == \"unknown\": state.unresolved_attempt_id = \"synthetic-unknown\"\n            elif change == \"disabled\": policy.enabled = False\n            elif change == \"media_disabled\": policy.media_enabled = False\n        with pytest.raises(Refused):\n            prepare(authority, account, spec(price))\n        with Session(database[1]) as s:\n            assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 0\n    finally:\n        store.close()\n\n\n@pytest.mark.parametrize(\"stage\", [\"prepare\", \"queued\", \"admitted\"])\n@pytest.mark.parametrize(\"guard\", [\"owned\", \"commerce\"])\ndef test_paid_photo_retains_purchase_checks_at_every_boundary(database, monkeypatch, stage, guard):\n    store, authority, account = prepared(database, monkeypatch)\n    try:\n        history_hold(database[1], account, stale=True)\n        identity = None if stage == \"prepare\" else prepare(authority, account, spec(1200))\n        grant = authority.admit(TENANT, account, identity) if stage == \"admitted\" else None\n        if guard == \"owned\":\n            with Session(database[1]) as s, s.begin():\n                s.add(VaultSend(account_id=account, fan_id=FAN, media_id=13, was_purchased=True))\n        else:\n            from onlyfans_runtime import commerce\n            monkeypatch.setattr(commerce, \"manual_held\", lambda *args, **kwargs: True)\n        if stage == \"prepare\":\n            with pytest.raises(Refused, match=\"already owned|commerce evidence\"):\n                prepare(authority, account, spec(1200))\n        elif stage == \"queued\":\n            assert authority.admit(TENANT, account, identity) == \"cancelled\"\n        else:\n            assert authority.consume_dispatch(TENANT, grant) is None\n        with Session(database[1]) as s:\n            assert s.scalar(select(func.count()).select_from(Message)) == 0\n            assert s.scalar(select(func.count()).select_from(ContentOffer)) == 0\n            if identity is not None:\n                assert s.get(OfTextIntent, (account, identity)).wire_started_at is None\n    finally:\n        store.close()\n","test_manual_vault_composer_pg.py":"\"\"\"Manual vault sends on disposable PostgreSQL; no provider or production credentials.\"\"\"\nimport json\nimport pytest\nfrom sqlalchemy import select, func\nfrom sqlalchemy.orm import Session\nfrom test_onlyfans_foundation_pg import database\nfrom test_onlyfans_vault_pg import sync\nfrom test_onlyfans_connections_pg import TENANT, ACTOR\nfrom db.models import Fan, OfConversationState, CatalogItem, Message, VaultItem, VaultSend, ContentOffer\nfrom db.onlyfans_models import OfRuntime\nfrom db.onlyfans_delivery_models import OfTextIntent\nfrom onlyfans_runtime.store import Refused, utcnow\nfrom onlyfans_runtime.manual_media import normalize\nfrom onlyfans_runtime.text_delivery import TextAuthority, SyntheticTextTransport\n\nFAN = 101\n\ndef prepared(database, monkeypatch):\n    store, account, _, _ = sync(database, monkeypatch)\n    with Session(database[1]) as s, s.begin():\n        runtime = s.get(OfRuntime, account)\n        runtime.enabled = True\n        runtime.recovery_needed = False\n        runtime.last_sync_at = utcnow()\n        s.add(Fan(account_id=account, fan_id=FAN)); s.flush()\n        s.add(OfConversationState(account_id=account, fan_id=FAN, mode=\"human_controlled\",\n            revision=0, takeover_state=\"none\", requires_attention=False))\n    authority = TextAuthority(store)\n    authority.configure(TENANT, account, expected_revision=0, enabled=True, media_enabled=True,\n        limit_units=20, throttle_seconds=1, actor=ACTOR, reason=\"Synthetic manual vault test\")\n    return store, authority, account\n\ndef spec(price=1234):\n    return {\"mediaIds\":[\"11\",\"13\"],\"previewIds\":[\"11\"] if price else [],\"priceCents\":price}\n\ndef prepare(authority, account, value, key=\"manual-media-one\", body=\"Selected scenic media.\"):\n    return authority.prepare(TENANT, account, FAN, command_key=key, expected_revision=0,\n        body=body, origin=\"manual\", actor=ACTOR, manual_media=value)\n\n@pytest.mark.parametrize(\"value\", [\n    {\"mediaIds\":[],\"previewIds\":[],\"priceCents\":500},\n    {\"mediaIds\":[\"11\",\"11\"],\"previewIds\":[],\"priceCents\":500},\n    {\"mediaIds\":[11],\"previewIds\":[],\"priceCents\":500},\n    {\"mediaIds\":[\"11\"],\"previewIds\":[\"12\"],\"priceCents\":500},\n    {\"mediaIds\":[\"11\"],\"previewIds\":[\"11\"],\"priceCents\":500},\n    {\"mediaIds\":[\"11\"],\"previewIds\":[\"11\"],\"priceCents\":0},\n    {\"mediaIds\":[\"11\"],\"previewIds\":[],\"priceCents\":True},\n    {\"mediaIds\":[\"11\"],\"previewIds\":[],\"priceCents\":299},\n    {\"mediaIds\":[\"11\"],\"previewIds\":[],\"priceCents\":20001},\n    {\"mediaIds\":[\"11\"],\"previewIds\":[],\"priceCents\":500,\"url\":\"https://untrusted.invalid\"},\n    {\"mediaIds\":[\"9223372036854775808\"],\"previewIds\":[],\"priceCents\":500},\n])\ndef test_invalid_terms_are_refused(value):\n    with pytest.raises(Refused): normalize(value)\n\n@pytest.mark.parametrize(\"price\", [0, 300, 1234, 20000])\ndef test_explicit_price_files_previews_and_exactly_once_receipt(database, monkeypatch, price):\n    store, authority, account = prepared(database, monkeypatch)\n    identity = prepare(authority, account, spec(price))\n    assert prepare(authority, account, spec(price)) == identity\n    with Session(database[1]) as s:\n        row = s.get(OfTextIntent, (account, identity))\n        assert row.price_cents == price and json.loads(row.media_json) == [11,13]\n        assert s.get(CatalogItem,row.catalog_item_id).enabled is False\n        assert s.scalar(select(func.count()).select_from(CatalogItem)) == 1\n    wire = SyntheticTextTransport(account)\n    assert authority.dispatch(TENANT,account,identity,wire) == \"accepted\"\n    assert authority.dispatch(TENANT,account,identity,wire) == \"accepted\"\n    assert len(wire.calls) == 1\n    assert wire.calls[0].price_cents == price and wire.calls[0].media_ids == (11,13)\n    with Session(database[1]) as s:\n        message = s.get(Message,(account,FAN,9001))\n        assert message.price_cents == price and message.media_count == 2\n        assert s.scalar(select(func.count()).select_from(VaultSend)) == 2\n        assert s.scalar(select(func.count()).select_from(ContentOffer)) == (1 if price else 0)\n    store.close()\n\ndef test_changed_file_is_not_sent(database,monkeypatch):\n    store,authority,account=prepared(database,monkeypatch)\n    identity=prepare(authority,account,spec())\n    with Session(database[1]) as s,s.begin():\n        s.get(VaultItem,(account,13)).removed_at=utcnow()\n    wire=SyntheticTextTransport(account)\n    assert authority.dispatch(TENANT,account,identity,wire) == \"cancelled\"\n    assert wire.calls == []\n    store.close()\n\ndef test_price_change_cannot_reuse_command_and_ai_cannot_use_manual_media(database,monkeypatch):\n    store,authority,account=prepared(database,monkeypatch)\n    prepare(authority,account,spec())\n    with pytest.raises(Refused,match=\"idempotency\"):\n        prepare(authority,account,spec(1300))\n    with pytest.raises(Refused,match=\"invalid manual media selection\"):\n        authority.prepare(TENANT,account,FAN,command_key=\"not-ai\",expected_revision=0,\n            body=\"Scenic media.\",origin=\"automated\",actor=ACTOR,manual_media=spec())\n    store.close()\n\ndef test_ambiguous_send_is_never_retried(database,monkeypatch):\n    store,authority,account=prepared(database,monkeypatch)\n    identity=prepare(authority,account,spec())\n    wire=SyntheticTextTransport(account,outcome=\"accepted_lost_response\")\n    assert authority.dispatch(TENANT,account,identity,wire) == \"unknown\"\n    assert authority.dispatch(TENANT,account,identity,wire) == \"unknown\"\n    assert len(wire.calls) == 1\n    store.close()\n\n@pytest.mark.parametrize(\"price\", [0, 1200])\ndef test_media_without_caption(database, monkeypatch, price):\n    store, authority, account = prepared(database, monkeypatch)\n    identity = prepare(authority, account, spec(price), body=\"\")\n    wire = SyntheticTextTransport(account)\n    assert authority.dispatch(TENANT, account, identity, wire) == \"accepted\"\n    assert len(wire.calls) == 1 and wire.calls[0].body == \"\"\n    from onlyfans_runtime.native_protocol import request\n    payload = json.loads(request(wire.calls[0]))\n    assert payload[\"mediaFiles\"] == [11, 13] and payload[\"price\"] == price / 100\n    store.close()\n","test_onlyfans_manual_pg.py":"\"\"\"Operator manual-message API over real PG and the common intent ledger.\"\"\"\nimport hashlib\n\nimport pytest\nfrom fastapi import FastAPI\nfrom fastapi.testclient import TestClient\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom test_onlyfans_foundation_pg import database, seed\nfrom test_onlyfans_text_delivery_pg import ACCOUNT, FAN, TENANT, configured\nfrom db.models import (CatalogItem, ContentOffer, Fan, GrokCall, Message,\n    OfConversationState, Transaction, VaultSend)\nfrom db.onlyfans_delivery_models import OfTextIntent\nfrom onlyfans_read.contract import conversation_id_for\nfrom onlyfans_runtime.text_delivery import TextAuthority, SyntheticTextTransport\n\n\nfrom onlyfans_runtime.ledger import _coverage_receipt\n\ndef context(database, monkeypatch, *, mode=\"human_controlled\", enabled=True):\n    from onlyfans_commands.api import router\n    from onlyfans_commands.settings import HEADER, SCHEMA\n    store, authority = configured(database, mode=mode)\n    monkeypatch.setenv(\"ONLYFANS_PROCESS_ROLE\", \"api\")\n    monkeypatch.setenv(\"ONLYFANS_API_TOKEN\", \"synthetic-read-token\")\n    monkeypatch.setenv(\"ONLYFANS_CONTROL_TOKEN\", \"synthetic-control-token\")\n    monkeypatch.setenv(\"ONLYFANS_CONTROL_TENANT\", TENANT)\n    monkeypatch.setenv(\"ONLYFANS_MANUAL_ENABLED\", \"1\" if enabled else \"0\")\n    app = FastAPI(); app.include_router(router); app.state.control_store = store\n    headers = {\"Authorization\": \"Bearer synthetic-control-token\", HEADER: SCHEMA}\n    url = f\"/onlyfans/control/v1/accounts/{ACCOUNT}/conversations/{conversation_id_for(ACCOUNT, FAN)}\"\n    body = dict(action=\"manual_message\", expectedRevision=0,\n        commandKey=hashlib.sha256(b\"synthetic-manual-1\").hexdigest(),\n        actor=\"op-session:\" + \"a\" * 64, body=\"An operator-authored reply.\")\n    return store, authority, app, headers, url, body\n\n\ndef test_manual_ack_is_queued_and_exact_retry_never_creates_another_send(database, monkeypatch):\n    store, authority, app, headers, url, body = context(database, monkeypatch)\n    with Session(database[1]) as s, s.begin():\n        s.get(OfConversationState, (ACCOUNT, FAN)).takeover_state = \"effective\"\n    with TestClient(app) as client:\n        first = client.post(url, headers=headers, json=body)\n        assert first.status_code == 200\n        ack = first.json()\n        assert ack[\"outcome\"] == \"queued\" and ack[\"intentId\"] and ack[\"recordedRevision\"] == 0\n        assert client.post(url, headers=headers, json=body).json() == ack\n        with Session(database[1]) as s:\n            assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 1\n            assert s.scalar(select(func.count()).select_from(Message)) == 0\n        wire = SyntheticTextTransport(ACCOUNT)\n        assert authority.dispatch(TENANT, ACCOUNT, ack[\"intentId\"], wire) == \"accepted\"\n        # An acknowledgement is historical evidence, not an instruction to send\n        # again or a current-state badge. Its exact retry remains the same.\n        assert client.post(url, headers=headers, json=body).json() == ack\n        assert len(wire.calls) == 1\n        changed = {**body, \"body\": \"Different text with the same request key.\"}\n        assert client.post(url, headers=headers, json=changed).status_code == 409\n        with Session(database[1]) as s:\n            assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 1\n            assert s.scalar(select(func.count()).select_from(Message).where(Message.direction == \"out\")) == 1\n    store.close()\n\n\ndef test_lost_manual_ack_retry_recovers_same_durable_intent(database, monkeypatch):\n    store, _, app, headers, url, body = context(database, monkeypatch)\n    original = TextAuthority.prepare\n    called = []\n    def lose_first_ack(self, *args, **kwargs):\n        identity = original(self, *args, **kwargs)\n        called.append(identity)\n        if len(called) == 1:\n            raise RuntimeError(\"Synthetic response lost after commit\")\n        return identity\n    monkeypatch.setattr(TextAuthority, \"prepare\", lose_first_ack)\n    with TestClient(app) as client:\n        assert client.post(url, headers=headers, json=body).status_code == 500\n        retry = client.post(url, headers=headers, json=body)\n        assert retry.status_code == 200\n        assert called == [retry.json()[\"intentId\"]] * 2\n    with Session(database[1]) as s:\n        assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 1\n        assert s.scalar(select(func.count()).select_from(Message)) == 0\n    store.close()\n\n\n@pytest.mark.parametrize(\"mode\", [\"automated\", \"paused\", \"no_contact\"])\ndef test_manual_requires_effective_human_control_and_respects_no_contact(database, monkeypatch, mode):\n    store, _, app, headers, url, body = context(database, monkeypatch, mode=mode)\n    with TestClient(app) as client:\n        assert client.post(url, headers=headers, json=body).status_code == 409\n    with Session(database[1]) as s:\n        assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 0\n    store.close()\n\n\n@pytest.mark.parametrize(\"change\", [\"stale_revision\", \"takeover_requested\", \"muted\"])\ndef test_manual_rejects_stale_or_blocked_operator_snapshot(database, monkeypatch, change):\n    store, _, app, headers, url, body = context(database, monkeypatch)\n    with Session(database[1]) as s, s.begin():\n        if change == \"stale_revision\":\n            s.get(OfConversationState, (ACCOUNT, FAN)).revision = 1\n        elif change == \"takeover_requested\":\n            s.get(OfConversationState, (ACCOUNT, FAN)).takeover_state = \"requested\"\n        else:\n            s.get(Fan, (ACCOUNT, FAN)).is_muted = True\n    with TestClient(app) as client:\n        assert client.post(url, headers=headers, json=body).status_code == 409\n    with Session(database[1]) as s:\n        assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 0\n    store.close()\n\n\ndef test_manual_purpose_gate_foreign_scope_and_strict_json(database, monkeypatch):\n    store, _, app, headers, url, body = context(database, monkeypatch, enabled=False)\n    other = seed(database[0], database[1], account=\"acc-b\", tenant=\"tenant-b\")\n    with TestClient(app) as client:\n        assert client.post(url, headers=headers, json=body).status_code == 503\n        monkeypatch.setenv(\"ONLYFANS_MANUAL_ENABLED\", \"1\")\n        assert client.post(url, headers={**headers, \"Authorization\": \"Bearer synthetic-read-token\"}, json=body).status_code == 401\n        foreign = f\"/onlyfans/control/v1/accounts/acc-b/conversations/{conversation_id_for('acc-b', FAN)}\"\n        assert client.post(foreign, headers=headers, json=body).status_code == 404\n        raw_headers = {**headers, \"Content-Type\": \"application/json\"}\n        assert client.post(url, headers=raw_headers, content='{\"action\":\"manual_message\",\"action\":\"manual_message\"}').status_code == 400\n        assert client.post(url, headers=raw_headers, content='{\"expectedRevision\":NaN}').status_code == 400\n        assert client.post(url, headers=headers, json={**body, \"body\": \"x\" * 4001}).status_code == 400\n        assert client.post(url, headers=headers, json={**body, \"extra\": True}).status_code == 400\n    other.close(); store.close()\n\n\ndef test_paid_manual_api_uses_native_wire_without_model_or_purchase(database, monkeypatch):\n    from test_onlyfans_media_pg import shelf\n    from test_onlyfans_provider_pg import fake_requests\n    from test_onlyfans_provider_adapters import credential\n    from onlyfans_runtime.provider_connector import NativeProviderConnector\n    from ownership import owned_media_in_session\n    store, authority, app, headers, url, body = context(database, monkeypatch)\n    item = shelf(database[1])\n    authority.configure(TENANT, ACCOUNT, expected_revision=1, enabled=True, media_enabled=True,\n        transport_kind=\"native\", limit_units=20, throttle_seconds=1,\n        actor=\"synthetic-operator\", reason=\"Native paid manual API acceptance\")\n    payload = {**body, \"catalogItemId\": item}\n    calls, requests = fake_requests(database, monkeypatch)\n    with TestClient(app) as client:\n        assert client.post(url, headers=headers, json=payload).status_code == 409, \"Native media waits for fresh ledger coverage\"\n        from datetime import timedelta\n        from db.onlyfans_models import OfRuntime\n        from db.onlyfans_ledger_models import OfLedgerScan\n        from onlyfans_runtime.store import utcnow\n        from test_onlyfans_provider_adapters import OWNER\n        with Session(database[1]) as s, s.begin():\n            now = utcnow()\n            s.add(OfLedgerScan(account_id=ACCOUNT, binding_id=s.get(OfRuntime, ACCOUNT).binding_id,\n                owner_id=OWNER, connection_revision=1, window_start=now-timedelta(days=90),\n                window_end=now, page_offset=0, status=\"idle\", next_poll_at=now+timedelta(minutes=1),\n                last_complete_at=now, last_full_at=now, updated_at=now))\n            s.flush()\n            scan=s.get(OfLedgerScan,ACCOUNT);scan.coverage_json=_coverage_receipt(scan)\n        queued = client.post(url, headers=headers, json=payload)\n        assert queued.status_code == 200, queued.text\n        ack = queued.json()\n        assert ack[\"outcome\"] == \"queued\"\n        assert client.post(url, headers=headers, json=payload).json() == ack\n        with Session(database[1]) as s:\n            intent = s.get(OfTextIntent, (ACCOUNT, ack[\"intentId\"]))\n            assert intent.catalog_item_id == item and intent.price_cents == 1000\n            assert intent.media_json == \"[11,12,13]\" and intent.preview_json == \"[11]\"\n            assert s.scalar(select(func.count()).select_from(Message)) == 0\n            assert s.scalar(select(func.count()).select_from(ContentOffer)) == 0\n        monkeypatch.setenv(\"ONLYFANS_PROCESS_ROLE\", \"worker\")\n        monkeypatch.setenv(\"DATABASE_URL\", database[0])\n        wire = NativeProviderConnector(credential())\n        assert authority.dispatch(TENANT, ACCOUNT, ack[\"intentId\"], wire) == \"accepted\"\n        assert calls == [] and sum(method == \"POST\" for method, _, _ in requests) == 1\n        import json\n        sent = json.loads(next(raw for method, _, raw in requests if method == \"POST\"))\n        assert sent[\"mediaFiles\"] == [11, 12, 13] and sent[\"previews\"] == [11] and sent[\"price\"] == 10\n        monkeypatch.setenv(\"ONLYFANS_PROCESS_ROLE\", \"api\")\n        assert client.post(url, headers=headers, json=payload).json() == ack\n        assert client.post(url, headers=headers, json={**payload, \"catalogItemId\": None}).status_code == 409\n    with Session(database[1]) as s:\n        assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 1\n        assert s.get(Message, (ACCOUNT, FAN, 9001)).is_paid is False\n        assert s.scalar(select(ContentOffer)).status == \"open\"\n        assert s.scalar(select(func.count()).select_from(VaultSend)) == 3\n        assert s.scalar(select(func.count()).select_from(VaultSend).where(VaultSend.was_purchased.is_(True))) == 0\n        assert s.scalar(select(func.count()).select_from(Transaction)) == 0\n        assert s.scalar(select(func.count()).select_from(GrokCall)) == 0\n        assert owned_media_in_session(s, ACCOUNT, FAN) == set()\n    store.close()\n\n\ndef test_manual_paid_api_rejects_foreign_item_and_unapproved_media_without_partial_intent(database, monkeypatch):\n    from test_onlyfans_media_pg import shelf, media_policy\n    store, authority, app, headers, url, body = context(database, monkeypatch)\n    item = shelf(database[1]); media_policy(authority)\n    other = seed(database[0], database[1], account=\"acc-b\", tenant=\"tenant-b\")\n    foreign = shelf(database[1], account=\"acc-b\")\n    with TestClient(app) as client:\n        assert client.post(url, headers=headers, json={**body, \"catalogItemId\": foreign}).status_code == 409\n        with Session(database[1]) as s, s.begin(): s.get(CatalogItem, item).is_free_teaser = True\n        assert client.post(url, headers=headers, json={**body, \"catalogItemId\": item}).status_code == 409\n    with Session(database[1]) as s:\n        assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 0\n        assert s.scalar(select(func.count()).select_from(Message)) == 0\n        assert s.scalar(select(func.count()).select_from(Transaction)) == 0\n    other.close(); store.close()\n\n\n@pytest.mark.parametrize(\"stage\", [\"queued\", \"admitted\"])\ndef test_manual_paid_api_price_change_cannot_refresh_or_consume_frozen_offer(database, monkeypatch, stage):\n    from test_onlyfans_media_pg import shelf, media_policy\n    store, authority, app, headers, url, body = context(database, monkeypatch)\n    item = shelf(database[1]); media_policy(authority)\n    payload = {**body, \"catalogItemId\": item}\n    with TestClient(app) as client:\n        queued = client.post(url, headers=headers, json=payload)\n        assert queued.status_code == 200\n        ack = queued.json()\n        grant = authority.admit(TENANT, ACCOUNT, ack[\"intentId\"]) if stage == \"admitted\" else None\n        with Session(database[1]) as s, s.begin(): s.get(CatalogItem, item).price_cents = 1100\n        if grant is None:\n            assert authority.admit(TENANT, ACCOUNT, ack[\"intentId\"]) == \"cancelled\"\n        else:\n            assert authority.consume_dispatch(TENANT, grant) is None\n        assert client.post(url, headers=headers, json=payload).json() == ack\n    with Session(database[1]) as s:\n        intent = s.get(OfTextIntent, (ACCOUNT, ack[\"intentId\"]))\n        assert intent.price_cents == 1000 and intent.status == \"cancelled\" and intent.wire_started_at is None\n        assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 1\n        assert s.scalar(select(func.count()).select_from(Message)) == 0\n        assert s.scalar(select(func.count()).select_from(ContentOffer)) == 0\n    store.close()\n\n\ndef test_manual_optional_item_validation_and_legacy_text_shape(database, monkeypatch):\n    store, _, app, headers, url, body = context(database, monkeypatch)\n    with TestClient(app) as client:\n        for item in (True, 0, -1, 2**31, \"catalog-1\", [], {}):\n            assert client.post(url, headers=headers, json={**body, \"catalogItemId\": item}).status_code == 400\n        for extra in ({\"priceCents\": 1}, {\"mediaIds\": [11]}, {\"previews\": [11]}):\n            assert client.post(url, headers=headers, json={**body, **extra}).status_code == 400\n        assert client.post(url, headers=headers, json={**body, \"body\": \"invalid\\x00text\"}).status_code == 400\n        first = client.post(url, headers=headers, json=body)\n        assert first.status_code == 200\n        # Optional null does not reinterpret or fork the old text-only intent.\n        assert client.post(url, headers=headers, json={**body, \"catalogItemId\": None}).json() == first.json()\n        with Session(database[1]) as s:\n            intent = s.get(OfTextIntent, (ACCOUNT, first.json()[\"intentId\"]))\n            assert intent.catalog_item_id is None and intent.media_json == \"[]\" and intent.price_cents == 0\n            assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 1\n    store.close()\n\n\ndef test_manual_paid_api_lost_ack_keeps_item_bound_to_same_intent(database, monkeypatch):\n    from test_onlyfans_media_pg import shelf, media_policy\n    store, authority, app, headers, url, body = context(database, monkeypatch)\n    item = shelf(database[1]); media_policy(authority)\n    payload = {**body, \"catalogItemId\": item}\n    original, called = TextAuthority.prepare, []\n    def lose_first_ack(self, *args, **kwargs):\n        identity = original(self, *args, **kwargs)\n        called.append(identity)\n        if len(called) == 1: raise RuntimeError(\"Synthetic paid acknowledgement lost after commit\")\n        return identity\n    monkeypatch.setattr(TextAuthority, \"prepare\", lose_first_ack)\n    with TestClient(app) as client:\n        assert client.post(url, headers=headers, json=payload).status_code == 500\n        recovered = client.post(url, headers=headers, json=payload)\n        assert recovered.status_code == 200\n        assert called == [recovered.json()[\"intentId\"]] * 2\n        assert client.post(url, headers=headers, json=body).status_code == 409\n    with Session(database[1]) as s:\n        assert s.scalar(select(func.count()).select_from(OfTextIntent)) == 1\n        intent = s.get(OfTextIntent, (ACCOUNT, recovered.json()[\"intentId\"]))\n        assert intent.catalog_item_id == item and intent.price_cents == 1000\n        assert s.scalar(select(func.count()).select_from(Message)) == 0\n    store.close()\n"}
